#!/usr/bin/env python3
"""Task FT-C1b (v0.235): the mappings page, with the fake MIDI device of taskFT_C1a.py (its harness is reused).
   python3 tools/ui-tests/taskFT_C1b.py [index.html] [out dir]"""
import sys, os, json
HERE = os.path.dirname(os.path.abspath(__file__))
exec(open(os.path.join(HERE, 'taskFT_C1a.py'), encoding='utf-8').read().split("with sync_playwright() as p:")[0])
V = lambda R, id: J(R, "+(C=>C.spec.n(C.get()))(CT.get(%s)).toFixed(4)" % json.dumps(id))

with sync_playwright() as p:
    b, pg, logs, R = boot(p)
    ok(tuple(map(int, R("VERSION").split('.'))) >= (0, 235), 'version 0.235 or later', R("VERSION"))
    kn = J(R, "[...document.querySelectorAll('#fxin .kn[data-c^=\"fx:\"],#fxin .vb[data-c^=\"fx:\"]')].filter(e=>e.offsetWidth&&e.dataset.c.split(':').length===3).slice(0,4).map(e=>e.dataset.c)")
    ok(len(kn) >= 3, 'knobs to map', kn)
    R("FAKEMIDI.plug('Fake Keys','Fakeco');FAKEMIDI.plug('Pad Box','Fakeco')"); R("ctlPage()"); pg.wait_for_timeout(400)
    W = '#ctlWin .ctlpg'
    s = J(R, "{pg:!!document.querySelector('#ctlWin .ctlpg'),dev:[...document.querySelectorAll('#ctlWin .cmdev b')].map(b=>b.textContent),last:document.querySelector('#ctlWin .cmlast').textContent}")
    ok(s['pg'] and s['dev'] == ['Fake Keys', 'Pad Box'], 'the page opens with both devices', s)
    ok(s['last'].startswith('Last message: nothing yet'), 'last message: nothing yet', s['last'])
    R("FAKEMIDI.msg('Pad Box',[0x91,40,99])"); pg.wait_for_timeout(150)
    ok(J(R, "document.querySelector('#ctlWin .cmlast').textContent") == 'Last message: Pad Box, Note 40 (channel 2), value 99', 'the last message line follows the controller', J(R, "document.querySelector('#ctlWin .cmlast').textContent"))
    R("FAKEMIDI.msg('Pad Box',[0x81,40,0])")
    # learn two mappings, one per device
    for dev, cc, k in (('Fake Keys', 21, kn[0]), ('Pad Box', 22, kn[1])):
        R("midiLearn(true)"); pg.locator('#fxin [data-c=%s]' % json.dumps(k)).first.click(); R("FAKEMIDI.msg(%s,[0xB0,%d,64])" % (json.dumps(dev), cc)); R("midiLearn(false)")
    pg.wait_for_timeout(200)
    ok(J(R, "document.querySelectorAll('#ctlWin .cmr:not(.h)').length") == 2, 'both mappings listed')
    pg.locator(W + ' select[data-k2=filter]').select_option('Pad Box'); pg.wait_for_timeout(100)
    s = J(R, "[...document.querySelectorAll('#ctlWin .cmr:not(.h) span:first-child')].map(e=>e.textContent)")
    ok(s == ['Pad Box'] and '1 of 2' in J(R, "document.querySelector('#ctlWin .cmn').textContent"), 'filter by device', s)
    pg.locator(W + ' select[data-k2=filter]').select_option(''); pg.wait_for_timeout(100)
    # the edit row: range
    mid = J(R, "UI.ctl.maps.find(m=>m.num===21).id")
    pg.locator(W + ' .cmr[data-m=%s] button[data-k2=open]' % json.dumps(mid)).click(); pg.wait_for_timeout(100)
    ok(J(R, "!!document.querySelector('#ctlWin .cmd[data-for=%s]')" % json.dumps(mid)), 'the edit row opens')
    pg.screenshot(path=os.path.join(OUT, 'c1b_page.png'))
    inp = pg.locator(W + ' input[data-k2=min][data-m=%s]' % json.dumps(mid)); inp.fill('20'); inp.press('Enter'); pg.wait_for_timeout(80)
    inp = pg.locator(W + ' input[data-k2=max][data-m=%s]' % json.dumps(mid)); inp.fill('60'); inp.press('Enter'); pg.wait_for_timeout(80)
    m = J(R, "UI.ctl.maps.find(m=>m.id===%s)" % json.dumps(mid))
    ok(abs(m['min'] - .2) < 1e-9 and abs(m['max'] - .6) < 1e-9, 'range 20 to 60 % from the edit row', (m['min'], m['max']))
    ok('20 to 60%' in J(R, "document.querySelector('#ctlWin .cmr[data-m=%s]').textContent" % json.dumps(mid)), 'the row shows the range')
    ok(J(R, "document.querySelectorAll('#ctlWin .cmd[data-for=%s] small')[0].textContent" % json.dumps(mid)) != '', 'the range shows the control\'s own value next to the percent')
    R("ctlEdit(%s,{take:'jump'})" % json.dumps(mid)); R("FAKEMIDI.msg('Fake Keys',[0xB0,21,0])"); a = V(R, kn[0]); R("FAKEMIDI.msg('Fake Keys',[0xB0,21,127])"); c = V(R, kn[0])
    ok(abs(a - .2) < .01 and abs(c - .6) < .01, 'the knob now covers 20 to 60 %', (a, c))
    # knob kind and speed
    pg.locator(W + ' select[data-k2=enc][data-m=%s]' % json.dumps(mid)).select_option('rel2c'); pg.wait_for_timeout(80)
    ok(J(R, "UI.ctl.maps.find(m=>m.id===%s).enc" % json.dumps(mid)) == 'rel2c' and J(R, "!!document.querySelector('#ctlWin select[data-k2=sens]')"), 'knob kind set to endless; the speed appears')
    pg.locator(W + ' select[data-k2=sens][data-m=%s]' % json.dumps(mid)).select_option('2'); pg.wait_for_timeout(80)
    R("(C=>{C.set(C.spec.v(.4));paintSel(%s)})(CT.get(%s))" % (json.dumps(kn[0]), json.dumps(kn[0]))); R("FAKEMIDI.msg('Fake Keys',[0xB0,21,1])")
    ok(abs(V(R, kn[0]) - (.4 + 2 / 127 * .4)) < .003, 'speed Fast: one step moves twice as far (inside the 40 % range)', V(R, kn[0]))
    pg.locator(W + ' select[data-k2=enc][data-m=%s]' % json.dumps(mid)).select_option('abs'); pg.wait_for_timeout(80)
    # feedback switch
    R("FAKEMIDI.sent.length=0"); R("(C=>{C.set(C.spec.v(.5));paintSel(%s)})(CT.get(%s))" % (json.dumps(kn[0]), json.dumps(kn[0]))); pg.wait_for_timeout(150)
    ok(any(x['data'][:2] == [0xB0, 21] for x in J(R, "FAKEMIDI.sent")), 'feedback on: a mouse move is sent back')
    pg.locator(W + ' input[data-k2=fb][data-m=%s]' % json.dumps(mid)).uncheck(); pg.wait_for_timeout(80); R("FAKEMIDI.sent.length=0")
    R("(C=>{C.set(C.spec.v(.3));paintSel(%s)})(CT.get(%s))" % (json.dumps(kn[0]), json.dumps(kn[0]))); pg.wait_for_timeout(150)
    ok(J(R, "UI.ctl.maps.find(m=>m.id===%s).fb" % json.dumps(mid)) is False and not any(x['data'][:2] == [0xB0, 21] for x in J(R, "FAKEMIDI.sent")), 'Send back off: nothing is sent')
    pg.locator(W + ' input[data-k2=fb][data-m=%s]' % json.dumps(mid)).check(); pg.wait_for_timeout(80)
    # learn again from the list
    pg.locator(W + ' button[data-k2=relearn][data-m=%s]' % json.dumps(mid)).click(); pg.wait_for_timeout(80)
    ok(J(R, "CTL.relearn") == mid and 'Move a knob now' in J(R, "document.querySelector('#ctlWin .rl.on').textContent"), 'Learn again waits for a message')
    R("FAKEMIDI.msg('Pad Box',[0xB2,50,10])"); pg.wait_for_timeout(100)
    m = J(R, "UI.ctl.maps.find(m=>m.id===%s)" % json.dumps(mid))
    ok([m['dev'], m['type'], m['ch'], m['num'], m['target']] == ['Pad Box', 'cc', 2, 50, kn[0]] and J(R, "CTL.relearn") is None, 'learned again: Pad Box CC 50 (channel 3) now moves the same control, range kept', m)
    ok(abs(m['min'] - .2) < 1e-9, 'the range is kept')
    pg.locator(W + ' button[data-k2=relearn][data-m=%s]' % json.dumps(mid)).click(); pg.keyboard.press('Escape'); pg.wait_for_timeout(80)
    ok(J(R, "CTL.relearn") is None, 'Esc stops Learn again')
    pg.locator(W + ' button[data-k2=relearn][data-m=%s]' % json.dumps(mid)).click(); R("FAKEMIDI.msg('Fake Keys',[0x90,61,90])"); R("FAKEMIDI.msg('Fake Keys',[0x80,61,0])"); pg.wait_for_timeout(80)
    m = J(R, "UI.ctl.maps.find(m=>m.id===%s)" % json.dumps(mid))
    ok(m['type'] == 'note' and m['num'] == 61 and m['take'] == 'jump', 'learned again with a key: it becomes a switch', m)
    # defaults for new mappings
    pg.locator(W + ' select[data-k2=dtake]').select_option('scale'); pg.locator(W + ' select[data-k2=dscope]').select_option('project'); pg.wait_for_timeout(80)
    R("midiLearn(true)"); pg.locator('#fxin [data-c=%s]' % json.dumps(kn[2])).first.click(); R("FAKEMIDI.msg('Fake Keys',[0xB0,23,64])"); R("midiLearn(false)")
    s = J(R, "{u:[UI.ctlTake,UI.ctlScope],p:S.ctl&&S.ctl.maps.map(m=>[m.num,m.take])}")
    ok(s['u'] == ['scale', 'project'] and s['p'] == [[23, 'scale']], 'defaults: new mappings take Scale and are kept in this project', s)
    R("UI.ctlTake='pickup';UI.ctlScope='global'"); R("ctlPagePaint()")
    # scope move and delete from the list
    pid = J(R, "S.ctl.maps[0].id"); pg.locator(W + ' select[data-k2=scope][data-m=%s]' % json.dumps(pid)).select_option('global'); pg.wait_for_timeout(80)
    ok(J(R, "S.ctl.maps.length===0&&UI.ctl.maps.some(m=>m.id===%s)" % json.dumps(pid)), 'moved from this project to every project')
    n = J(R, "ctlAll().length"); pg.locator(W + ' button[data-k2=del][data-m=%s]' % json.dumps(pid)).click(); pg.wait_for_timeout(80)
    ok(J(R, "ctlAll().length") == n - 1, 'deleted from the list')
    s = J(R, "{t:[...document.querySelectorAll('#ctlWin .ctlpg button,#ctlWin .ctlpg select,#ctlWin .ctlpg input')].filter(e=>!e.title&&!e.dataset.tip).length,em:/—/.test(document.querySelector('#ctlWin .ctlpg').textContent)}")
    ok(s['t'] == 0 and not s['em'], 'tooltips on every control, no em dashes', s)
    pg.locator(W + ' .cmr:not(.h) button[data-k2=open]').first.click(); pg.wait_for_timeout(100)
    pg.screenshot(path=os.path.join(OUT, 'c1b_page2.png'))
    R("const c=$('#liteChk');if(!c.checked){c.checked=true;c.dispatchEvent(new Event('change'))}"); pg.wait_for_timeout(600); pg.screenshot(path=os.path.join(OUT, 'c1b_light.png'))
    R("const c=$('#liteChk');c.checked=false;c.dispatchEvent(new Event('change'))")
    # Settings hook: the same page in any element
    R("window.__h=document.createElement('div');__h.style.cssText='position:fixed;left:10px;top:10px;width:700px;height:400px;z-index:99999;background:#111';document.body.appendChild(__h);FT_HOOKS.controllersPage(__h)"); pg.wait_for_timeout(200)
    ok(J(R, "__h.classList.contains('ctlpg')&&__h.querySelectorAll('.cmr:not(.h)').length===ctlAll().length&&!!__h.querySelector('.cmlast')"), 'FT_HOOKS.controllersPage draws the same page into a Settings page body')
    R("__h.remove();CTL.host=null")
    # feedback while playing follows automation (no drawing)
    k3 = json.dumps(kn[2]); R("midiLearn(true)"); pg.locator('#fxin [data-c=%s]' % k3).first.click(); R("FAKEMIDI.msg('Fake Keys',[0xB0,24,0])"); R("midiLearn(false)")
    R("start()"); pg.wait_for_timeout(300); R("FAKEMIDI.sent.length=0"); R("CT.get(%s).set(CT.get(%s).spec.v(.75))" % (k3, k3)); pg.wait_for_timeout(300)
    ok([0xB0, 24, round(.75 * 127)] in [x['data'] for x in J(R, "FAKEMIDI.sent")], 'while playing, a control moved without drawing (as automation does) is still sent back', J(R, "FAKEMIDI.sent.map(x=>x.data)"))
    R("stop()"); pg.wait_for_timeout(300); n0 = J(R, "CTL.pollN"); pg.wait_for_timeout(400)
    ok(J(R, "CTL.pollT") == 0 and J(R, "CTL.pollN") == n0, 'stopped: the check stops too (nothing runs while idle)')
    ok(not logs, 'no console errors', logs)
    b.close()
print('\n%d checks, %d failed' % (N[0], len(FAIL)))
for f in FAIL: print('  FAIL', f)
sys.exit(1 if FAIL else 0)
